fontFaceCss:
@font-face { font-display: swap; font-family: HaasUnicaSH-Medium; font-style: normal; src: url("../fonts/HaasUnicaSH-Medium.woff2") format("woff2"), url("../fonts/HaasUnicaSH-Medium.woff") format("woff"), url("../fonts/HaasUnicaSH-Medium.otf") format("opentype"); unicode-range: U+0-2A, U+2C-3F, U+41-FFFF; }
@font-face { font-display: swap; font-family: HaasUnicaSH-Regular; font-style: normal; src: url("../fonts/HaasUnicaSH-Regular.woff2") format("woff2"), url("../fonts/HaasUnicaSH-Regular.woff") format("woff"), url("../fonts/HaasUnicaSH-Regular.otf") format("opentype"); unicode-range: U+0-2A, U+2C-3F, U+41-FFFF; }
@font-face { font-display: swap; font-family: ductile; font-style: normal; src: url("../fonts/ductile.woff2") format("woff2"), url("../fonts/ductile.woff") format("woff"), url("/fonts/ductile.otf") format("opentype"); unicode-range: U+0-2A, U+2C-3F, U+41-FFFF; }
.ff-base { font-family: HaasUnicaSH-Medium, Helvetica, sans-serif; }
.ff-regular { font-family: HaasUnicaSH-Regular, Helvetica, sans-serif; }
.ff-display { font-family: ductile, Helvetica, sans-serif; }
body { background-color: var(--c-bg); color: rgb(0, 0, 0); font-family: HaasUnicaSH-Medium, Helvetica, sans-serif; font-size: 1.6rem; line-height: 100%; overflow-x: hidden; overscroll-behavior-x: contain; -webkit-font-smoothing: antialiased; }
